    enonce: "<span class=\"q\">1) </span>نعتبر العبارتين: <span dir=\"ltr\" class=\"expr\">A = -2 + ((-8) + a)   ;   B = -7 - [-4 - (a - 2)]</span><br><span class=\"q\">2) </span>نعتبر العبارتين: <span dir=\"ltr\" class=\"expr\">A = -3 + (1 + x)   ;   B = -8 - [-3 - (x - 3)]</span><br><span class=\"q\">3) </span>نعتبر العبارتين: <span dir=\"ltr\" class=\"expr\">A = -5 + (4 + x)   ;   B = -2 - [0 - (x - -6)]</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نختصر الأولى","math":"<span dir=\"ltr\" class=\"expr\">-2 + ((-8) + a) = a - 10</span>"},{"quoi":"نختصر الثانية","math":"<span dir=\"ltr\" class=\"expr\">-7 - [-4 - (a - 2)] = a - 5</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(a - 10) - (a - 5) = -5</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-5 < 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a - 10 < a - 5</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نختصر الأولى","math":"<span dir=\"ltr\" class=\"expr\">-3 + (1 + x) = x - 2</span>"},{"quoi":"نختصر الثانية","math":"<span dir=\"ltr\" class=\"expr\">-8 - [-3 - (x - 3)] = x - 8</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(x - 2) - (x - 8) = 6</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">6 > 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x - 2 > x - 8</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نختصر الأولى","math":"<span dir=\"ltr\" class=\"expr\">-5 + (4 + x) = x - 1</span>"},{"quoi":"نختصر الثانية","math":"<span dir=\"ltr\" class=\"expr\">-2 - [0 - (x - -6)] = x + 4</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(x - 1) - (x + 4) = -5</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-5 < 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x - 1 < x + 4</span>"}],
